SELECT cust_list.*, tb_comp.*, companyn.*, Trim$([fname])+"  "+Trim$([pname]) AS name, Trim$(nz([adress_c]))+" "+Trim$(nz([city_c])) AS caddr, Trim$(nz([city])) AS mcity, DateDiff("yyyy",[bdate],Date()) AS gil, "טל: " & nz([tel_c]) & "  " & "פקס: " & nz([fax__c]) AS tl, tb_comp.rnum AS p1
FROM companyn, cust_list INNER JOIN tb_comp ON cust_list.numw=tb_comp.wnum
WHERE (((tb_comp.rnum)=[Forms]![f_ad_tests]![rnum]));

SELECT tb_cust_list.*, qprt_achecks.*, tb_cust_list.numw AS p1, Trim$([fname])+"  "+Trim$([pname]) AS name, Trim$(nz([adress_c]))+" "+Trim$(nz([city_c])) AS caddr, Trim$(nz([city])) AS mcity, DateDiff("yyyy",[bdate],Date()) AS gil, "טל: " & nz([tel_c]) & "  " & "פקס: " & nz([fax__c]) AS tl, IIf(nz([sel])<>"",[sel],[tel]) AS qtel
FROM tb_cust_list INNER JOIN qprt_achecks ON tb_cust_list.numw=qprt_achecks.numw
WHERE (((tb_cust_list.numw)=[Forms]![customers]![numw]));

SELECT cust_list.*, checks.*, cust_list.numw AS p1, companyn.*, checks.bdka AS q, Trim$([fname])+"  "+Trim$([pname]) AS name, Trim$(nz([adress_c]))+" "+Trim$(nz([city_c])) AS caddr, Trim$(nz([city]))+" "+Trim$(nz([mikud])) AS mcity, DateDiff("yyyy",[bdate],Date()) AS gil, "טל: " & nz([tel_c]) & "  " & "פקס: " & nz([fax__c]) AS tl
FROM companyn, cust_list INNER JOIN checks ON cust_list.numw=checks.numw
WHERE (((cust_list.numw)=Forms!customers!numw) And ((checks.bdka)=True));

SELECT cust_list.*, tb_quest.*, tb_quest.rnum AS p1, companyn.*, Trim$([fname])+"  "+Trim$([pname]) AS name, Trim$(nz([adress_c]))+" "+Trim$(nz([city_c])) AS caddr, Trim$(nz([city]))+" "+Trim$(nz([mikud])) AS mcity, DateDiff("yyyy",[bdate],Date()) AS gil, "טל: " & nz([tel_c]) & "  " & "פקס: " & nz([fax__c]) AS tl
FROM companyn, cust_list INNER JOIN tb_quest ON cust_list.numw=tb_quest.wnum
WHERE (((tb_quest.rnum)=[Forms]![f_quest]![rnum]));

SELECT adchecks.*, adchecks.bdikanum AS s, adchecks.numw AS q, adchecks.caddate AS dw
FROM qlast_achecks INNER JOIN adchecks ON (qlast_achecks.qtyp=adchecks.qtyp) AND (qlast_achecks.dt=adchecks.caddate) AND (qlast_achecks.numw=adchecks.numw)
ORDER BY adchecks.bdikanum DESC;

SELECT checks.*, checks.bdikanum AS s, checks.numw AS q, checks.chdate AS dw
FROM qlast_checks INNER JOIN checks ON (qlast_checks.numw=checks.numw) AND (qlast_checks.dt=checks.chdate) AND (qlast_checks.qtyp=checks.qtyp)
ORDER BY checks.bdikanum DESC;
